#!/usr/bin/env bash
# Round 7 asset draws, ONE at a time via studio/bin/art.sh. usage: batch.sh [name...]  (FORCE=1 to redo)
cd /c/Users/Admin/Documents/Msjelly/studio/long-cat-out/art-src/r7
S="Art style (must match across the whole set): soft painterly 3D cartoon like a polished 2026 mobile game, smooth chunky rounded felt-toy shapes, clean soft shading and gentle gradients, NOT photorealistic, NOT flat vector, no outlines. Palette: sage green walls #689A8D, honey oak wood #BF7948 with darker oak #8E5530, ivory #FFF0D3, rust red #BD582F, warm cream #fff6e5. One warm sunlight from the upper right, soft shadows falling down-left. Absolutely no text, no letters, no numbers, no logo, no watermark."
K="Place every item on a flat solid pure magenta #ff00ff background with nothing else on it so it can be keyed out; no shadow on the background, items must not touch each other or the image edge."
G="Arrange as a clean grid with wide magenta gaps between items, each item fully visible and the same scale."
g(){ n=$1; shift; if [ -s "$n.png" ] && [ -z "$FORCE" ]; then echo "skip $n"; return; fi; echo "gen $n"; /c/Users/Admin/Documents/Msjelly/studio/bin/art.sh "$(pwd -W)/$n.png" "$*" >/dev/null 2>&1; ls -la "$n.png" 2>&1 | awk '{print $5}'; }
W=("$@")
run(){ if [ ${#W[@]} -eq 0 ]; then return 0; fi; for w in "${W[@]}"; do [ "$w" = "$1" ] && return 0; done; return 1; }

run bg_play_room && g bg_play_room "Portrait 2:3 full-bleed game background, NO magenta. Cozy cat cafe boarding room seen from slightly above: sage green wall at the top with a sunny bay window upper right and a sheer curtain, a wide honey oak table filling the lower 85 percent of the image, hanging pothos plant top-left, wicker basket with a yarn ball bottom-right, potted leafy plant bottom-left, soft warm light shafts across the wood. The whole centre of the table is EMPTY, plain evenly lit oak planks, ready for a game board. No cats, no characters. $S"
run table_top && g table_top "Single object: a rectangular stitched rust-red felt rug lying flat seen from straight above, portrait proportion about 7 wide by 9 tall, thick soft woolen rim with visible thickness and a cream stitched border inside, the inner area is a plain flat ivory #FFF0D3 field that is completely empty, soft contact shadow down-left. $K $S"
run tile_ivory && g tile_ivory "Single square image filling the whole frame, NO magenta: a seamless tileable close-up of ivory #FFF0D3 matte ceramic floor tile surface, one tile with very subtle bevelled edge and faint hairline grout, perfectly flat top-down lighting, extremely subtle. $S"
run tex_felt && g tex_felt "Single square image filling the whole frame, NO magenta: seamless tileable soft neutral light-grey wool felt fabric texture, fine fibres, very subtle, no pattern, no shading gradient, top-down. $S"
run belt_wood && g belt_wood "Single object: a wooden toy conveyor belt shelf, long horizontal, viewed side-on with a slight top-down tilt, dark brown wooden slats on the moving surface, honey oak side rails, a round brass roller wheel at each end, about 5 times wider than tall, empty. $K $S"
run carriers_open && g carriers_open "Eight plastic pet carriers, door OPEN swung to the left showing a dark empty interior and a silver wire grille on the door, three-quarter view, chunky toy-like, a small blank cream tag plate on each roof. Each carrier a different glossy colour: orange, sky blue, bubblegum pink, leaf green, violet purple, mint teal, sunny yellow, cherry red. $G 4 columns by 2 rows. $K $S"
run carriers_shut && g carriers_shut "Eight plastic pet carriers, door CLOSED with a silver wire grille, a happy cat face peeking out through the grille, three-quarter view, chunky toy-like, a small blank cream tag plate on each roof, same design as an open-door carrier. Each carrier a different glossy colour: orange, sky blue, bubblegum pink, leaf green, violet purple, mint teal, sunny yellow, cherry red. The cat inside matches the carrier colour. $G 4 columns by 2 rows. $K $S"
run bench_plank && g bench_plank "Single object: a long honey oak bench plank with thick edges and two short legs, seen slightly from above, exactly 5 round recessed hollows evenly spaced along the top, empty hollows, about 5 times wider than tall. $K $S"
run cushion && g cushion "Single object: one round oatmeal-beige felt cushion with a small centre button, soft and chunky, seen slightly from above at a 3/4 angle, smooth cartoon felt, not photorealistic. $K $S"
for e in happy sleepy cheeky; do
 case $e in happy) E="wide open happy smile, big sparkling round eyes looking forward";; sleepy) E="eyes peacefully closed as curved sleepy lines, tiny gentle smile";; cheeky) E="one eye winking, tongue sticking out cheekily, a little smirk";; esac
 run heads_$e && g heads_$e "Eight front-facing heads of chubby cartoon cats, felt-textured fur, ears up, two white paws tucked under the chin, expression: $E. Eight cats in different colours and patterns: orange with darker orange tabby stripes, sky blue with darker blue polka dots, bubblegum pink with red-pink hearts, leaf green with dark green zigzag, violet purple with yellow stars, mint teal with white clouds, sunny yellow with orange spots, cherry red with cream diamonds. Same head shape for all. $G 4 columns by 2 rows in that order. $K $S"
done
run curls && g curls "Eight cats curled asleep in a round ball, seen slightly from above, chubby felt-textured, white tail tip, eyes closed, each a different colour and pattern: orange with tabby stripes, sky blue with polka dots, bubblegum pink with hearts, leaf green with zigzag, violet purple with stars, mint teal with clouds, sunny yellow with spots, cherry red with diamonds. $G 4 columns by 2 rows in that order. $K $S"
run btns && g btns "Three round glossy game buttons, thick soft rim, each with a pale icon: a sunny yellow button with a glowing lightbulb, a sky blue button with a butterfly net, a violet purple button with a curved undo arrow. Slight bevel and highlight, light from upper right. In a single row, wide gaps. $K $S"
run ui_kit && g ui_kit "A set of game UI parts, empty (no text, no icons inside): 1) a wide cream #fff6e5 rounded panel with a 3 pixel dark oak border and soft inner shadow, 2) a small dark-oak wooden plaque tab with rounded ends, 3) a cream pill-shaped counter holder with a dark oak rim, 4) a huge glossy orange rounded-pill PLAY button blank with a darker orange bottom edge, 5) a smaller glossy green rounded button blank, 6) a round cream button with an oak rim, 7) a round honey-yellow badge circle. $G 4 columns by 2 rows. $K $S"
run tab_icons && g tab_icons "Eight small chunky glossy game icons: a red-roofed house, a pink cat paw print, a pink shopping bag, a golden trophy cup, a wrapped red gift box with a bow, a calendar with a clock, a wooden padlock, a glowing yellow hammer. $G 4 columns by 2 rows in that order. $K $S"
for r in "counter|a cat cafe ground floor with wooden hanging lamps and a big arched sunny window, bare plank floor and bare walls" "cushion|a cosy cushion lounge floor with pastel walls and a skylight and wooden beams" "window|a bright window reading room with three tall sunny windows and a built-in window seat alcove, bare floor" "patio|a garden patio with a brick floor, climbing vines on a fence wall, an open sky with sunlight and a low brick planter wall" "rooftop|an open rooftop terrace at golden hour with a low parapet wall, a distant town skyline and soft sunset sky"; do
 IFS='|' read -r id desc <<<"$r"
 run room_${id}_bare && g room_${id}_bare "Large cutaway interior scene, square, full-bleed, NO magenta: $desc. Seen from a slightly raised 3/4 angle in a narrow cat cafe townhouse, warm sunlight from the upper right, wood beams, the EMPTY floor in the centre and left ready for furniture, a clear open floor area, no furniture, no characters. $S"
done
for r in "counter|ground floor|warm brick and a striped awning" "cushion|first floor|pastel walls" "window|second floor|big windows" "patio|garden patio extension|a brick terrace with a fence" "rooftop|rooftop terrace|open sky and a parapet"; do
 IFS='|' read -r id nm desc <<<"$r"
 run room_${id}_shell && g room_${id}_shell "Single object, wide 2:1: the front cross-section of one narrow townhouse $nm under CONSTRUCTION: bare wooden frame and floor slab, wooden scaffold poles and planks, stacked bricks, a dust sheet draped over a corner, $desc, open front so the empty interior is visible. $K $S"
done
run building_base && g building_base "Portrait 2:3, full-bleed, NO magenta: a cobblestone town street at morning with a blue sky, soft clouds, small neighbouring townhouses on both sides cut off at the image edges, a plain empty plot in the centre for a narrow townhouse (flat cobbled ground), flower pots and a lamp post at the corners, a pavement strip at the bottom. $S"
run building_floors && g building_floors "Four front cross-section modules of ONE narrow cat cafe townhouse, each exactly the same width and same height with a flat top edge and a flat bottom edge so they stack vertically, all the same plain cream stucco side walls: 1) ground floor with an arched shop door and striped awning and a lit warm cafe interior, 2) a finished upper floor lit warmly with cosy lounge window glow and window boxes, 3) an upper floor under construction with scaffold poles and no front wall, 4) a pale translucent light-blue BLUEPRINT ghost of a floor, outline only. Wide 2:1 modules, 2 columns by 2 rows. $K $S"
run building_roof && g building_roof "Two roof pieces for a narrow townhouse, same width: 1) a terracotta tiled gable roof with a small chimney and a round attic window, 2) a flat rooftop terrace with a low parapet railing and string lights. Seen front-on. $G Side by side. $K $S"
run crane && g crane "Single object: a small yellow construction tower crane swinging with a rope and a hook hanging with a roof beam piece, chunky toy-like, square. $K $S"
for a in counter window cushion patio rooftop; do
 case $a in
  counter) L="a honey-oak cafe counter with espresso machine; a glass pastry display dome with cakes; three green pendant lamps; a wooden chalkboard menu easel with doodles but no letters; a round cafe table with two stools; a big monstera potted plant";;
  window) L="a built-in cushioned window seat; a cluster of hanging plants in macrame baskets; a tall wooden bookshelf with colourful books; a multi-level cat tree with a sisal post; a round cream rug with a paw print; a strand of warm string lights";;
  cushion) L="a fluffy round rug; a fabric floor lamp with a warm shade; a cubby bookshelf with baskets; a cat hammock on a frame; a cushioned window bench; a giant pile of soft cushions";;
  patio) L="a flower planter box with blooming flowers; a vine pergola arch; a little stone fountain; a string-light post; a wooden sun lounger; a patio table with an umbrella and two chairs";;
  rooftop) L="a fairy-light canopy; a brass telescope on a tripod; a potted lemon tree; a tall cat climbing tower; two bean bags; a snack grill cart";;
 esac
 run decor_$a && g decor_$a "Six separate furniture and decor items for a cat cafe, three-quarter view, chunky, readable, each isolated: $L. Same scale feel, items in order left to right, top row then bottom row. $G 3 columns by 2 rows. $K $S"
done
run res_idle && g res_idle "Eight chubby cartoon cat characters sitting upright, three-quarter view, felt-textured soft fur, each a named resident: 1) cream cat with a red collar and gold bell, 2) brown tabby cat with a white chef hat and red neckerchief, 3) grey tabby cat with a yellow star hairclip and blue overalls, 4) fluffy orange cat with green eyes and a red bow tie, 5) fluffy white cat with a blue scarf, 6) black cat with a straw hat and green overalls, 7) calico cat with a flower crown, 8) grey tabby cat in an aviator cap with goggles, a sheepskin collar and a red scarf. $G 4 columns by 2 rows in that order. $K $S"
run res_job && g res_job "Eight chubby cartoon cat characters doing a cosy job, three-quarter view, felt-textured fur, same eight residents in this order: 1) cream cat with red collar and gold bell carrying a tray with a cake and a latte, 2) brown tabby cat in a white chef hat holding a rolling pin by a tray of croissants, 3) grey tabby cat with a yellow star hairclip napping curled on a pillow, 4) fluffy orange cat with green eyes and red bow tie playing with a pink ball of yarn, 5) fluffy white cat with a blue scarf napping on a cushion, 6) black cat with a straw hat watering a small plant with a can, 7) calico cat with a flower crown holding a bouquet, 8) grey tabby cat in an aviator cap with goggles looking through a small telescope. $G 4 columns by 2 rows in that order. $K $S"
run tipjars && g tipjars "Four identical glass tip jars with a paw-print sticker and a slot lid, seen slightly from above, filled with gold paw-print coins to a different level: empty, a quarter full, half full, completely full and heaped. Left to right in one row. $K $S"
run guest && g guest "Single object: a shy fluffy cream cat sitting on a small woven doormat with a tiny brown suitcase beside it, chubby, felt-textured, three-quarter view. $K $S"
run hud_icons && g hud_icons "Eight small chunky glossy game icons: a plump red heart, a gold coin with a paw print, a gold five-point star, a wooden treasure chest with brass trim, a gold ribbon medal, a pink ribbon rosette, a blue fish treat, a pink cat toy yarn ball. $G 4 columns by 2 rows in that order. $K $S"
